---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div"> & {
  defaultIndex?: number
  orientation?: "horizontal" | "vertical"
  drag?: boolean
  loop?: boolean
  multiple?: boolean
}

const {
  class: className,
  defaultIndex,
  orientation = "horizontal",
  drag,
  loop,
  multiple,
  ...props
} = Astro.props
---

<div
  data-slot="carousel"
  data-default-index={defaultIndex}
  data-orientation={orientation}
  data-drag={drag}
  data-loop={loop}
  data-multiple={multiple}
  class={cn("group/carousel relative", className)}
  {...props}
>
  <slot />
</div>

<script>
  import { create } from "@data-slot/carousel"

  import { observeCarouselVisibility } from "./carousel-visibility"

  const visibility = new Map<HTMLElement, () => void>()
  const controllers: ReturnType<typeof create> = []
  const initialize = () => {
    controllers.push(...create())
    for (const root of document.querySelectorAll<HTMLElement>(
      '[data-slot="carousel"][data-multiple="true"]'
    )) {
      if (!visibility.has(root))
        visibility.set(root, observeCarouselVisibility(root))
    }
  }
  initialize()
  document.addEventListener("astro:page-load", initialize)
  document.addEventListener("astro:before-swap", () => {
    for (const controller of controllers) controller.destroy()
    controllers.length = 0
    for (const cleanup of visibility.values()) cleanup()
    visibility.clear()
  })
</script>

/** Keep the visible portion of a multi-slide carousel accessible. */
export function observeCarouselVisibility(root: HTMLElement) {
  const content = root.querySelector<HTMLElement>(
    '[data-slot="carousel-content"]'
  )
  if (!content) return () => {}

  let frame: number | undefined
  const update = () => {
    const viewport = content.getBoundingClientRect()
    const vertical = root.dataset.orientation === "vertical"
    for (const item of content.children) {
      if (!(item instanceof HTMLElement)) continue
      if (item.dataset.slot !== "carousel-item") continue
      resize.observe(item)
      const bounds = item.getBoundingClientRect()
      const visible = vertical
        ? bounds.bottom > viewport.top + 1 && bounds.top < viewport.bottom - 1
        : bounds.right > viewport.left + 1 && bounds.left < viewport.right - 1
      if (item.inert === visible) item.inert = !visible
      const hidden = String(!visible)
      if (item.getAttribute("aria-hidden") !== hidden)
        item.setAttribute("aria-hidden", hidden)
    }
  }
  const schedule = () => {
    frame ??= requestAnimationFrame(() => {
      frame = undefined
      update()
    })
  }

  // The single-slide primitive updates these attributes after scroll settles.
  // Observe that update as well as geometry so visible links stay operable.
  const mutation = new MutationObserver(update)
  mutation.observe(content, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["inert", "aria-hidden"],
  })
  const resize = new ResizeObserver(schedule)
  resize.observe(content)
  content.addEventListener("scroll", schedule, { passive: true })
  update()

  return () => {
    mutation.disconnect()
    resize.disconnect()
    content.removeEventListener("scroll", schedule)
    if (frame !== undefined) cancelAnimationFrame(frame)
  }
}
